model.view:
{
  "version": 1,
  "state": [
    {
      "id": "down",
      "when": {
        "eq": [
          {
            "var": "live"
          },
          "FALSE"
        ]
      },
      "label": "On Air is down"
    },
    {
      "id": "capture",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"pieceReady\""
        ]
      },
      "label": "Ready for capture or finish"
    },
    {
      "id": "write",
      "when": {
        "any": [
          {
            "eq": [
              {
                "var": "phase"
              },
              "\"writing\""
            ]
          },
          {
            "eq": [
              {
                "var": "phase"
              },
              "\"naming\""
            ]
          }
        ]
      },
      "label": "Writing or closing one piece"
    },
    {
      "id": "join-failed",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"joinFailed\""
        ]
      },
      "label": "Join failed; pieces kept"
    },
    {
      "id": "resolve",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"resolve\""
        ]
      },
      "label": "Waiting for the original hand-over result"
    },
    {
      "id": "handover-failed",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"handoverFailed\""
        ]
      },
      "label": "Hand-over failed; pieces kept"
    },
    {
      "id": "kept",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"kept\""
        ]
      },
      "label": "Handed over; retaining pieces"
    },
    {
      "id": "done",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"done\""
        ]
      },
      "label": "Retention passed; pieces removed"
    },
    {
      "id": "empty",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"empty\""
        ]
      },
      "label": "Nothing recorded"
    },
    {
      "id": "all",
      "when": true,
      "label": "Finishing and preserving the recording"
    }
  ],
  "step": [
    {
      "id": "crash",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "live"
              },
              "TRUE"
            ]
          },
          {
            "eq": [
              {
                "to": "live"
              },
              "FALSE"
            ]
          }
        ]
      },
      "label": "On Air dies"
    },
    {
      "id": "launch",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "live"
              },
              "FALSE"
            ]
          },
          {
            "eq": [
              {
                "to": "live"
              },
              "TRUE"
            ]
          }
        ]
      },
      "label": "Launch and recover from disk"
    },
    {
      "id": "all",
      "when": true,
      "label": "Advance the recording or receive a caller report"
    }
  ]
}

